import Foundation

/// Perceptual colormaps — smooth, perceptually-uniform ramps that map a value in
/// `0...1` to a color, the standard choice for turning a number (height, density,
/// a field value) into legible color.
///
/// ```swift
/// fill(Colormap.viridis.color(at: t))
/// ```
///
/// The data is the canonical public colormap data, reimplemented here:
/// `viridis`/`magma`/`inferno`/`plasma`/`cividis` are matplotlib's (CC0),
/// `turbo` is Google's (Apache-2.0), and `rocket`/`mako` are seaborn's (BSD-3).
public enum Colormap: Sendable, CaseIterable {
    case magma, inferno, plasma, viridis, cividis, rocket, mako, turbo

    /// The color at `t` in `0...1`, linearly interpolated across the 256-entry
    /// lookup table. `t` is clamped to the range.
    public func color(at t: Double) -> Color {
        let table = lookup
        let position = Swift.max(0, Swift.min(1, t)) * 255
        let i = Int(position)
        let frac = position - Double(i)
        let j = Swift.min(i + 1, 255)
        func channel(_ k: Int) -> Double {
            let a = table[i * 3 + k], b = table[j * 3 + k]
            return a + (b - a) * frac
        }
        return Color(red: channel(0), green: channel(1), blue: channel(2))
    }

    /// The color at `t` with the map treated as a cycle: `t` wraps by whole
    /// laps instead of clamping, so a growing value (an angle, the clock)
    /// tours the map forever. `color(at:)` is the clamped form; a `Palette`'s
    /// `color(at:)` already wraps this way.
    ///
    /// ```swift
    /// fill(Colormap.viridis.color(cycling: time / 8))
    /// ```
    ///
    /// Most maps end nowhere near where they begin, so each lap still lands a
    /// seam at the wrap; the seamless ring is `CosinePalette`, periodic by
    /// construction.
    public func color(cycling t: Double) -> Color {
        color(at: t - t.rounded(.down))
    }

    private var lookup: [Double] {
        switch self {
        case .magma: return Colormap.magmaLUT
        case .inferno: return Colormap.infernoLUT
        case .plasma: return Colormap.plasmaLUT
        case .viridis: return Colormap.viridisLUT
        case .cividis: return Colormap.cividisLUT
        case .rocket: return Colormap.rocketLUT
        case .mako: return Colormap.makoLUT
        case .turbo: return Colormap.turboLUT
        }
    }
}

